INSERT INTO v2.BODACC (BDCCR_ID_BDCCR, BDCCR_ID_BDCRC, BDCCR_TYPE_BODACC, BDCCR_ID_EVNPR, BDCCR_DATE_ENVOI, BDCCR_DATE_PUBLICITE,
